// Reads one entry of kMainOldEntries.
// Example: ToMainEntry(kMainOldEntries[0]) has position_index 0, old_axis 0 and weight 0.03125.
constexpr MainEntry ToMainEntry(const std::array<double, 9>& values) {
  return {
      .position_index = static_cast<int>(values[0]),
      .old_axis = static_cast<int>(values[1]),
      .old_lattice_index = {static_cast<int>(values[2]), static_cast<int>(values[3]), static_cast<int>(values[4])},
      .weight = values[5],
      .weight_change = {.x = values[6], .y = values[7], .z = values[8]},
  };
}

